<?php
require_once __DIR__ . '/../includes/bootstrap.php'; require_role('programme_manager');
require_once __DIR__ . '/_management_suite_helpers.php';
$user=current_user(); $conn=Database::getConnection(); $managerId=(int)($user['id']??$user['user_id']??0);
if($managerId<=0){http_response_code(403);exit('Invalid Programme Manager account.');}
$currentPage='resources'; $pageTitle='Resource Allocation & Utilisation'; $errors=[]; $ready=pm_table_exists($conn,'programme_resource_allocations');
$programmes=pm_suite_programmes($conn,$managerId); $cohorts=pm_suite_cohorts($conn,$managerId);
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!validate_csrf()) $errors[]='Session validation failed. Refresh and try again.';
 elseif(!$ready) $errors[]='Import database/programme_resource_targets_compliance.sql first.';
 else { $pid=(int)($_POST['programme_id']??0); $cid=(int)($_POST['cohort_id']??0); $name=trim((string)($_POST['resource_name']??'')); $cat=trim((string)($_POST['resource_category']??'Equipment')); $unit=trim((string)($_POST['unit_name']??'units')); $available=filter_var($_POST['available_quantity']??null,FILTER_VALIDATE_FLOAT); $allocated=filter_var($_POST['allocated_quantity']??null,FILTER_VALIDATE_FLOAT); $date=trim((string)($_POST['allocation_date']??'')); $notes=trim((string)($_POST['notes']??''));
 if(!pm_suite_valid_scope($conn,$pid,$cid,$managerId))$errors[]='Select a programme and cohort within your assigned scope.';
 if($name===''||mb_strlen($name)>160)$errors[]='Enter a resource name (maximum 160 characters).'; if($unit===''||mb_strlen($unit)>40)$errors[]='Enter a valid unit.'; if($available===false||$available<0||$allocated===false||$allocated<0)$errors[]='Quantities must be valid non-negative numbers.'; if($date!==''&&(!DateTime::createFromFormat('!Y-m-d',$date)||DateTime::createFromFormat('!Y-m-d',$date)->format('Y-m-d')!==$date))$errors[]='Choose a valid allocation date.';
 if(!$errors){$cv=$cid?:null;$dv=$date?:null;$s=$conn->prepare('INSERT INTO programme_resource_allocations(programme_id,cohort_id,resource_name,resource_category,unit_name,available_quantity,allocated_quantity,allocation_date,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)'); if($s){$s->bind_param('iisssddssi',$pid,$cv,$name,$cat,$unit,$available,$allocated,$dv,$notes,$managerId);$ok=$s->execute();$s->close();if($ok){set_flash('success','Resource allocation saved','The resource record has been added.');safe_redirect('programme/resources.php');}}$errors[]='The resource allocation could not be saved.'; }
 }
}
$rows=[];$stats=['available'=>0,'allocated'=>0,'shortages'=>0,'records'=>0];
if($ready){$s=$conn->prepare('SELECT r.*,p.name programme_name,c.name cohort_name,(r.available_quantity-r.allocated_quantity) remaining FROM programme_resource_allocations r JOIN programmes p ON p.id=r.programme_id LEFT JOIN cohorts c ON c.id=r.cohort_id WHERE p.programme_manager_id=? ORDER BY p.name,c.name,r.resource_name');if($s){$s->bind_param('i',$managerId);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}foreach($rows as $r){$stats['records']++;$stats['available']+=(float)$r['available_quantity'];$stats['allocated']+=(float)$r['allocated_quantity'];if((float)$r['remaining']<0)$stats['shortages']++;}}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=e($pageTitle)?> | Investhood IT</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="<?=url('css/styles.css')?>"><link rel="stylesheet" href="<?=url('css/programme_manager_enhancements.css')?>"><link rel="stylesheet" href="<?=url('css/programme_management_suite.css')?>"></head><body class="dashboard-page"><div class="dashboard"><?php require __DIR__.'/sidebar.php';?><main class="dashboard__main"><?php require __DIR__.'/navbar.php';?><div class="pm-suite"><?=render_flashes()?><section class="pm-suite-hero"><div><span class="pm-suite-eyebrow">Operational planning</span><h1>Resource Allocation &amp; Utilisation</h1><p>Track available and allocated resources across assigned programmes and cohorts. Shortages are flagged when allocations exceed recorded availability.</p></div></section><?php foreach($errors as $e1):?><div class="pm-suite-alert"><?=e($e1)?></div><?php endforeach;?><?php if(!$ready):?><div class="pm-suite-notice">Import <code>database/programme_resource_targets_compliance.sql</code> to enable resource tracking.</div><?php endif;?>
<section class="pm-suite-kpis"><article class="pm-suite-kpi"><small>Resource records</small><strong><?=$stats['records']?></strong><span>Across assigned programmes</span></article><article class="pm-suite-kpi"><small>Total available</small><strong><?=number_format($stats['available'],2)?></strong><span>Recorded quantities</span></article><article class="pm-suite-kpi"><small>Total allocated</small><strong><?=number_format($stats['allocated'],2)?></strong><span>Allocated quantities</span></article><article class="pm-suite-kpi"><small>Potential shortages</small><strong><?=$stats['shortages']?></strong><span>Allocations exceeding availability</span></article></section>
<div class="pm-suite-grid"><section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Allocate a resource</h2><p>Enter quantities using the same unit for availability and allocation.</p></div><form method="post" class="pm-suite-form"><?=csrf_field()?><div class="pm-suite-field"><label>Programme</label><select name="programme_id" required><option value="">Select programme</option><?php foreach($programmes as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Cohort (optional)</label><select name="cohort_id"><option value="0">Programme-wide</option><?php foreach($cohorts as $c):?><option value="<?=$c['id']?>"><?=e($c['programme_name'].' — '.$c['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Resource name</label><input name="resource_name" maxlength="160" required placeholder="e.g. Training laptops"></div><div class="pm-suite-field"><label>Category</label><select name="resource_category"><?php foreach(['Equipment','Training materials','Facilities','Personnel','Transport','Technology','Other'] as $v):?><option><?=e($v)?></option><?php endforeach;?></select></div><div class="pm-suite-two"><div class="pm-suite-field"><label>Unit</label><input name="unit_name" maxlength="40" value="units" required></div><div class="pm-suite-field"><label>Allocation date</label><input type="date" name="allocation_date"></div></div><div class="pm-suite-two"><div class="pm-suite-field"><label>Available quantity</label><input type="number" min="0" step="0.01" name="available_quantity" required></div><div class="pm-suite-field"><label>Allocated quantity</label><input type="number" min="0" step="0.01" name="allocated_quantity" required></div></div><div class="pm-suite-field"><label>Notes</label><textarea name="notes" rows="3"></textarea></div><button class="pm-suite-btn" <?=$ready?'':'disabled'?>>Save resource allocation</button></form></section>
<section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Resource register</h2><p>Remaining quantity is calculated as available less allocated.</p></div><div class="pm-suite-table-wrap"><table class="pm-suite-table"><thead><tr><th>Resource / scope</th><th>Available</th><th>Allocated</th><th>Remaining</th><th>Indicator</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="pm-suite-empty">No resource records have been added.</td></tr><?php else:foreach($rows as $r):$remaining=(float)$r['remaining'];?><tr><td><strong><?=e($r['resource_name'])?></strong><span class="pm-suite-muted"><?=e($r['resource_category'])?> · <?=e($r['programme_name'])?><?=!empty($r['cohort_name'])?' / '.e($r['cohort_name']):''?></span></td><td><?=number_format((float)$r['available_quantity'],2)?> <?=e($r['unit_name'])?></td><td><?=number_format((float)$r['allocated_quantity'],2)?></td><td><strong><?=number_format($remaining,2)?></strong></td><td><span class="pm-suite-pill <?=$remaining<0?'bad':($remaining==0?'warn':'good')?>"><?=$remaining<0?'Shortage':($remaining==0?'Fully allocated':'Available')?></span></td></tr><?php endforeach;endif;?></tbody></table></div></section></div></div></main></div><script src="<?=url('js/programme_manager_enhancements.js')?>"></script><script src="<?=url('js/original_pm_sidebar.js')?>"></script></body></html>
